BEGIN;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, display_name varchar(64), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_identities (wallet varchar(44) PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_challenges (id uuid PRIMARY KEY, wallet varchar(44) NOT NULL, message text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE INDEX auth_challenges_expiry ON auth_challenges(expires_at);
CREATE TABLE authentication_sessions (token_hash char(64) PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf_hash char(64) NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON authentication_sessions(expires_at);
CREATE TABLE creator_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), bio varchar(2000) NOT NULL DEFAULT '', avatar_asset_id uuid);
CREATE TABLE movements (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name varchar(100) NOT NULL, description varchar(2000) NOT NULL DEFAULT '', category varchar(32) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX movements_owner ON movements(owner_id,created_at,id);
CREATE TABLE movement_versions (id uuid PRIMARY KEY, movement_id uuid NOT NULL REFERENCES movements(id), version integer NOT NULL CHECK(version>0), source text NOT NULL CHECK(octet_length(source)<=32768), manifest jsonb NOT NULL, manifest_hash char(64) NOT NULL, validation_status varchar(32) NOT NULL DEFAULT 'compiled', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(movement_id,version));
CREATE TABLE movement_packs (id uuid PRIMARY KEY, movement_id uuid NOT NULL REFERENCES movements(id), owner_id uuid NOT NULL REFERENCES users(id), slug varchar(120) NOT NULL UNIQUE, title varchar(100) NOT NULL, description varchar(2000) NOT NULL DEFAULT '', category varchar(32) NOT NULL, status varchar(20) NOT NULL CHECK(status IN('draft','submitted','approved','published','rejected','delisted')), rights_confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE marketplace_listings (id uuid PRIMARY KEY, pack_id uuid NOT NULL REFERENCES movement_packs(id), version_id uuid NOT NULL REFERENCES movement_versions(id), seller_wallet varchar(44) NOT NULL, price_base_units numeric(20,0) NOT NULL CHECK(price_base_units>0 AND price_base_units<=18446744073709551615), mint varchar(44) NOT NULL, program_id varchar(44) NOT NULL, listing_address varchar(44) NOT NULL UNIQUE, manifest_hash char(64) NOT NULL, state varchar(20) NOT NULL CHECK(state IN('pending','active','delisted')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(pack_id,version_id));
CREATE INDEX active_listings ON marketplace_listings(created_at,id) WHERE state='active';
CREATE TABLE purchases (id uuid PRIMARY KEY, buyer_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES marketplace_listings(id), signature varchar(88) NOT NULL UNIQUE, status varchar(24) NOT NULL CHECK(status IN('submitted','pending','finalized','failed')), last_error varchar(500), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), finalized_at timestamptz);
CREATE INDEX reconciliation_queue ON purchases(next_attempt_at) WHERE status IN('submitted','pending');
CREATE TABLE onchain_receipts (address varchar(44) PRIMARY KEY, purchase_id uuid NOT NULL UNIQUE REFERENCES purchases(id), listing_address varchar(44) NOT NULL, buyer_wallet varchar(44) NOT NULL, manifest_hash char(64) NOT NULL, amount numeric(20,0) NOT NULL CHECK(amount>0), seller_paid numeric(20,0) NOT NULL CHECK(seller_paid>=0), platform_fee numeric(20,0) NOT NULL CHECK(platform_fee>=0), slot bigint NOT NULL, signature varchar(88) NOT NULL UNIQUE, verified_at timestamptz NOT NULL DEFAULT now(),CHECK(seller_paid+platform_fee=amount));
CREATE TABLE ownership_entitlements (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), version_id uuid NOT NULL REFERENCES movement_versions(id), receipt_address varchar(44) NOT NULL REFERENCES onchain_receipts(address), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,version_id));
CREATE TABLE reviews (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), listing_id uuid NOT NULL REFERENCES marketplace_listings(id), rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), body varchar(2000) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,listing_id));
CREATE TABLE favorites (user_id uuid NOT NULL REFERENCES users(id), movement_id uuid NOT NULL REFERENCES movements(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,movement_id));
CREATE TABLE simulation_projects (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name varchar(100) NOT NULL, configuration jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_scripts (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), movement_version_id uuid NOT NULL REFERENCES movement_versions(id), project_id uuid REFERENCES simulation_projects(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE training_jobs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), task varchar(40) NOT NULL, configuration jsonb NOT NULL, status varchar(24) NOT NULL CHECK(status IN('queued','running','cancelling','cancelled','failed','succeeded')), budget_seconds integer NOT NULL CHECK(budget_seconds BETWEEN 60 AND 14400), gpu_seconds_used numeric(14,3) NOT NULL DEFAULT 0 CHECK(gpu_seconds_used>=0), error varchar(1000), created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE TABLE training_artifacts (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES training_jobs(id), asset_hash char(64) NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE validation_results (id uuid PRIMARY KEY, version_id uuid REFERENCES movement_versions(id), artifact_id uuid REFERENCES training_artifacts(id), kind varchar(40) NOT NULL, passed boolean NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(version_id IS NOT NULL OR artifact_id IS NOT NULL));
CREATE TABLE media_assets (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), storage_key varchar(255) NOT NULL UNIQUE, content_hash char(64) NOT NULL, content_type varchar(100) NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>0), visibility varchar(8) NOT NULL CHECK(visibility IN('public','private')), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE creator_profiles ADD CONSTRAINT creator_avatar_fk FOREIGN KEY(avatar_asset_id) REFERENCES media_assets(id);
CREATE TABLE content_reports (id uuid PRIMARY KEY, reporter_id uuid NOT NULL REFERENCES users(id), pack_id uuid NOT NULL REFERENCES movement_packs(id), reason varchar(2000) NOT NULL, status varchar(20) NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions (id uuid PRIMARY KEY, admin_id uuid NOT NULL REFERENCES users(id), pack_id uuid NOT NULL REFERENCES movement_packs(id), action varchar(32) NOT NULL, reason varchar(2000) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action varchar(64) NOT NULL, target varchar(128), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_configuration (key varchar(100) PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_usage (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), input_tokens integer NOT NULL DEFAULT 0 CHECK(input_tokens>=0), output_tokens integer NOT NULL DEFAULT 0 CHECK(output_tokens>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_financial_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial records are immutable'; END; $$;
CREATE TRIGGER immutable_receipts BEFORE UPDATE OR DELETE ON onchain_receipts FOR EACH ROW EXECUTE FUNCTION protect_financial_record();
CREATE TRIGGER immutable_entitlements BEFORE UPDATE OR DELETE ON ownership_entitlements FOR EACH ROW EXECUTE FUNCTION protect_financial_record();
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON movement_versions FOR EACH ROW EXECUTE FUNCTION protect_financial_record();
COMMIT;
